use soroban_sdk::{contractimpl, Address, BytesN, Env, String};

use crate::errors::ContractError;
use crate::lifecycle::load;
use crate::types::{Session, SessionStatus};
use crate::{admin, events, payments, storage};
// Items generated by the #[contract] macro; needed so `impl SkillSyncEscrow` can live in this file
use crate::{SkillSyncEscrow, SkillSyncEscrowArgs, SkillSyncEscrowClient};

#[contractimpl]
impl SkillSyncEscrow {
    /// Locks funds in escrow with an additional insurance premium paid by the buyer.
    pub fn lock_funds_with_insurance(
        env: Env,
        session_id: BytesN<32>,
        buyer: Address,
        seller: Address,
        amount: i128,
        premium_bps: u32,
    ) -> Result<(), ContractError> {
        if amount <= 0 {
            return Err(ContractError::InvalidAmount);
        }
        let bps = if premium_bps > 0 {
            premium_bps
        } else {
            storage::get_insurance_premium_rate(&env)
        };
        if bps > 10_000 {
            return Err(ContractError::InvalidInsuranceRate);
        }
        buyer.require_auth();

        if storage::has_session(&env, &session_id) {
            return Err(ContractError::DuplicateSessionId);
        }

        let premium = amount
            .checked_mul(bps as i128)
            .ok_or(ContractError::Overflow)?
            / 10_000;

        let total_payment = amount
            .checked_add(premium)
            .ok_or(ContractError::Overflow)?;

        payments::pull_in(&env, &buyer, total_payment)?;

        if let Some(pool) = storage::get_insurance_pool(&env) {
            if premium > 0 {
                payments::pay_out(&env, &pool, premium)?;
            }
        } else {
            if premium > 0 {
                storage::add_insurance_pool_balance(&env, premium)?;
            }
        }

        let session = Session {
            buyer: buyer.clone(),
            seller: seller.clone(),
            amount,
            status: SessionStatus::Locked,
            created_at: env.ledger().sequence() as u64,
            completed_at: 0,
            dispute_opened_at: 0,
            dispute_resolved_at: 0,
            insured: true,
            premium_paid: premium,
            insurance_claimed: false,
            dispute_buyer_share: 0,
        };
        storage::save_session(&env, &session_id, &session);

        events::emit_funds_locked(&env, &session_id, &buyer, &seller, amount);
        events::emit_insurance_purchased(&env, &session_id, &buyer, amount, premium);
        Ok(())
    }

    /// Allows the buyer to claim insurance if dispute resolution gave them < 80% of the amount.
    pub fn claim_insurance(env: Env, session_id: BytesN<32>) -> Result<(), ContractError> {
        let mut session = load(&env, &session_id)?;
        if !session.insured {
            return Err(ContractError::NotInsured);
        }
        if session.insurance_claimed {
            return Err(ContractError::InsuranceAlreadyClaimed);
        }
        session.buyer.require_auth();
        if session.status != SessionStatus::Resolved {
            return Err(ContractError::InvalidSessionState);
        }

        let threshold = session.amount
            .checked_mul(80)
            .ok_or(ContractError::Overflow)?
            / 100;

        if session.dispute_buyer_share >= threshold {
            return Err(ContractError::NotEligibleForInsurance);
        }

        let shortfall = session.amount
            .checked_sub(session.dispute_buyer_share)
            .ok_or(ContractError::Overflow)?;

        let coverage_pct = storage::get_insurance_coverage_percentage(&env);
        let claim_amount = shortfall
            .checked_mul(coverage_pct as i128)
            .ok_or(ContractError::Overflow)?
            / 100;

        if claim_amount > 0 {
            let pool_balance = storage::get_insurance_pool_balance(&env);
            if pool_balance < claim_amount {
                return Err(ContractError::InsufficientInsurancePool);
            }
            storage::sub_insurance_pool_balance(&env, claim_amount)?;
            payments::pay_out(&env, &session.buyer, claim_amount)?;
        }

        session.insurance_claimed = true;
        storage::save_session(&env, &session_id, &session);

        events::emit_insurance_claim_paid(&env, &session_id, &session.buyer, claim_amount);
        Ok(())
    }

    /// Sets the insurance premium rate in basis points (0-10,000). Admin only.
    pub fn set_insurance_premium_rate(env: Env, premium_bps: u32) -> Result<(), ContractError> {
        let admin = admin::require_admin(&env)?;
        admin.require_auth();
        if premium_bps > 10_000 {
            return Err(ContractError::InvalidInsuranceRate);
        }
        let old = storage::get_insurance_premium_rate(&env);
        storage::set_insurance_premium_rate(&env, premium_bps);
        events::emit_insurance_premium_rate_updated(&env, old, premium_bps, &admin);
        Ok(())
    }

    /// Current insurance premium rate in basis points.
    pub fn get_insurance_premium_rate(env: Env) -> u32 {
        storage::get_insurance_premium_rate(&env)
    }

    /// Sets the insurance coverage percentage (0-100). Admin only.
    pub fn set_insurance_coverage_percentage(env: Env, coverage_percentage: u32) -> Result<(), ContractError> {
        let admin = admin::require_admin(&env)?;
        admin.require_auth();
        if coverage_percentage > 100 {
            return Err(ContractError::InvalidInsuranceRate);
        }
        let old = storage::get_insurance_coverage_percentage(&env);
        storage::set_insurance_coverage_percentage(&env, coverage_percentage);
        events::emit_insurance_coverage_percentage_updated(&env, old, coverage_percentage, &admin);
        Ok(())
    }

    /// Current insurance coverage percentage (0-100).
    pub fn get_insurance_coverage_percentage(env: Env) -> u32 {
        storage::get_insurance_coverage_percentage(&env)
    }

    /// Sets the insurance pool address. Admin only.
    pub fn set_insurance_pool(env: Env, pool: Address) -> Result<(), ContractError> {
        let admin = admin::require_admin(&env)?;
        admin.require_auth();
        let old = storage::get_insurance_pool(&env);
        storage::set_insurance_pool(&env, &pool);
        events::emit_insurance_pool_updated(&env, old.as_ref(), &pool, &admin);
        Ok(())
    }

    /// Current insurance pool address, if configured.
    pub fn get_insurance_pool(env: Env) -> Option<Address> {
        storage::get_insurance_pool(&env)
    }

    /// Current balance of the insurance pool managed by the contract.
    pub fn get_insurance_pool_balance(env: Env) -> i128 {
        storage::get_insurance_pool_balance(&env)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::test_utils::{balance, event, session_id, setup, Fixture};
    use crate::disputes::{RESOLUTION_REFUND_BUYER, RESOLUTION_PAY_SELLER, RESOLUTION_SPLIT};
    use soroban_sdk::testutils::{Address as _, Events, Ledger};
    use soroban_sdk::{IntoVal, Symbol};

    fn dispute_session(f: &Fixture, id: &BytesN<32>, amount: i128, buyer_share: i128) {
        f.client.lock_funds_with_insurance(id, &f.buyer, &f.seller, &amount, &100);
        f.client.complete_session(id);
        f.client.open_dispute(id, &f.buyer, &String::from_str(&f.env, "dispute"));
        let seller_share = amount - buyer_share;
        f.client.resolve_dispute(id, &RESOLUTION_SPLIT, &buyer_share, &seller_share);
    }

    #[test]
    fn lock_funds_with_insurance_charges_premium_and_emits_event() {
        let f = setup();
        let id = session_id(&f.env, 1);
        let buyer_before = balance(&f, &f.buyer);

        f.client.lock_funds_with_insurance(&id, &f.buyer, &f.seller, &1_000, &200); // 200 bps = 2% -> premium = 20

        assert_eq!(balance(&f, &f.buyer), buyer_before - 1_020);
        assert_eq!(f.client.get_insurance_pool_balance(), 20);

        let session = f.client.get_session(&id);
        assert!(session.insured);
        assert_eq!(session.premium_paid, 20);
        assert!(!session.insurance_claimed);

        let (topics, data) = event(&f.env, "InsurancePurchased");
        assert_eq!(
            topics,
            (Symbol::new(&f.env, "InsurancePurchased"), id.clone()).into_val(&f.env)
        );
        let data: (Address, i128, i128, u64) = data.into_val(&f.env);
        assert_eq!(data.0, f.buyer);
        assert_eq!(data.1, 1_000);
        assert_eq!(data.2, 20);
    }

    #[test]
    fn claim_insurance_covers_shortfall_when_buyer_gets_less_than_80_percent() {
        let f = setup();
        let id = session_id(&f.env, 2);
        f.env.as_contract(&f.contract_id, || {
            storage::add_insurance_pool_balance(&f.env, 1_000).unwrap();
        });
        soroban_sdk::token::StellarAssetClient::new(&f.env, &f.token).mint(&f.contract_id, &1_000);

        dispute_session(&f, &id, 1_000, 100);

        let buyer_before = balance(&f, &f.buyer);
        f.client.claim_insurance(&id);

        assert_eq!(balance(&f, &f.buyer), buyer_before + 900);
        assert!(f.client.get_session(&id).insurance_claimed);

        let (topics, data) = event(&f.env, "InsuranceClaimPaid");
        assert_eq!(
            topics,
            (Symbol::new(&f.env, "InsuranceClaimPaid"), id.clone()).into_val(&f.env)
        );
        let data: (Address, i128, u64) = data.into_val(&f.env);
        assert_eq!(data.0, f.buyer);
        assert_eq!(data.1, 900);
    }

    #[test]
    fn claim_insurance_rejects_when_buyer_gets_80_percent_or_more() {
        let f = setup();
        let id = session_id(&f.env, 3);
        f.env.as_contract(&f.contract_id, || {
            storage::add_insurance_pool_balance(&f.env, 1_000).unwrap();
        });
        soroban_sdk::token::StellarAssetClient::new(&f.env, &f.token).mint(&f.contract_id, &1_000);

        dispute_session(&f, &id, 1_000, 850);

        assert_eq!(
            f.client.try_claim_insurance(&id),
            Err(Ok(ContractError::NotEligibleForInsurance))
        );
    }

    #[test]
    fn admin_can_set_insurance_parameters() {
        let f = setup();
        assert_eq!(f.client.get_insurance_premium_rate(), 100);
        f.client.set_insurance_premium_rate(&150);
        assert_eq!(f.client.get_insurance_premium_rate(), 150);

        assert_eq!(f.client.get_insurance_coverage_percentage(), 100);
        f.client.set_insurance_coverage_percentage(&80);
        assert_eq!(f.client.get_insurance_coverage_percentage(), 80);

        let pool = Address::generate(&f.env);
        f.client.set_insurance_pool(&pool);
        assert_eq!(f.client.get_insurance_pool(), Some(pool));
    }
}
